-- SELECT only. Does not claim/read a queue message or settle/delete/retry data.
-- One statement provides a consistent data snapshot. All private rows stay in DB.
with row_hashes(relation,row_sha)as(
 select 'private.credit_wallets',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.credit_wallets t union all
 select 'private.credit_operations',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.credit_operations t union all
 select 'private.credit_ledger',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.credit_ledger t union all
 select 'private.credit_requests',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.credit_requests t union all
 select 'private.credit_admin_audit',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.credit_admin_audit t union all
 select 'private.quota_ledger',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.quota_ledger t union all
 select 'private.commerce_package_quotes',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.commerce_package_quotes t union all
 select 'private.commerce_package_orders',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.commerce_package_orders t union all
 select 'private.commerce_package_events',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.commerce_package_events t union all
 select 'private.commerce_package_generations',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.commerce_package_generations t union all
 select 'public.generations',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from public.generations t union all
 select 'private.generation_work',encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')from private.generation_work t
),wanted(relation)as(values('private.credit_wallets'),('private.credit_operations'),('private.credit_ledger'),('private.credit_requests'),('private.credit_admin_audit'),('private.quota_ledger'),('private.commerce_package_quotes'),('private.commerce_package_orders'),('private.commerce_package_events'),('private.commerce_package_generations'),('public.generations'),('private.generation_work')),
 protected as(select w.relation,count(h.row_sha)as rows,encode(sha256(convert_to(coalesce(string_agg(h.row_sha,''order by h.row_sha),''),'UTF8')),'hex')as rows_sha256 from wanted w left join row_hashes h using(relation)group by w.relation),
 counts as(select jsonb_build_object(
 'queueMessages',(select count(*)from pgmq.q_image_generation),
 'runnableGenerations',(select count(*)from public.generations g left join private.generation_work w on w.generation_id=g.id where g.status in('pending','processing')and not(coalesce(g.provider_submission_state='unknown',false)or coalesce(w.phase='unknown',false)or coalesce(g.error_code in('provider_reconciliation_required','provider_result_unknown','result_unknown'),false))),
 'historicalUnknownGenerations',(select count(*)from public.generations g left join private.generation_work w on w.generation_id=g.id where g.status in('pending','processing')and(coalesce(g.provider_submission_state='unknown',false)or coalesce(w.phase='unknown',false)or coalesce(g.error_code in('provider_reconciliation_required','provider_result_unknown','result_unknown'),false))),
 'processingPackageStages',(select count(*)from private.commerce_package_orders o cross join lateral jsonb_array_elements(coalesce(o.state->'stages','[]'))s where s->>'status'='processing'),
 'dueCleanupJobs',(select count(*)from private.cleanup_jobs where(attempts<5 and next_run_at<=statement_timestamp()+interval '22 minutes'and(status in('pending','failed')or status='processing'and coalesce(lease_until,updated_at+interval '5 minutes')<=statement_timestamp()+interval '22 minutes'))or(status='processing'and attempts>=5 and coalesce(lease_until,updated_at+interval '5 minutes')<=statement_timestamp()+interval '22 minutes')),
 'dueAccountCleanupJobs',(select count(*)from private.account_cleanup_jobs where(attempts<5 and next_run_at<=statement_timestamp()+interval '22 minutes'and(status in('pending','failed')or status='processing'and coalesce(lease_until,updated_at+interval '5 minutes')<=statement_timestamp()+interval '22 minutes'))or(status='processing'and attempts>=5 and coalesce(lease_until,updated_at+interval '5 minutes')<=statement_timestamp()+interval '22 minutes')),
 'dueOrphanReferenceIntents',(select count(*)from private.reference_write_intents x where x.cleanup_next_at<=statement_timestamp()+interval '22 minutes'and not exists(select 1 from public.reference_uploads r join public.sessions se on se.id=r.session_id join public.account_profiles a on a.user_id=r.user_id where r.id=x.reference_id and r.user_id=x.user_id and r.session_id=x.session_id and r.storage_path=x.storage_path and se.status='active'and a.status='active'and r.upload_expires_at>statement_timestamp()+interval '22 minutes'and((r.status='active'and r.write_state='ready')or(r.write_state='pending'and x.state='pending'and x.write_until>statement_timestamp()+interval '22 minutes')))and(x.state='pending'or exists(select 1 from storage.objects z where z.bucket_id='uploads'and z.name=x.storage_path))),
 'prunablePreviewRowsWithin22Minutes',(select count(*)from private.preview_usage_ledger where created_at<timezone('utc',statement_timestamp()+interval '22 minutes')-interval '8 days'or state='released'and created_at<timezone('utc',statement_timestamp()+interval '22 minutes')-interval '1 day'),
 'expiringPromotionRequestsWithin22Minutes',(select count(*)from private.reference_promotion_requests where expires_at<=statement_timestamp()+interval '22 minutes'),
 'accountCleanupLeases',(select count(*)from private.account_cleanup_jobs where status='processing'and coalesce(lease_until,updated_at+interval '5 minutes')>statement_timestamp()),
 'referenceCleanupLeases',(select count(*)from private.reference_write_intents where cleanup_until>statement_timestamp()),
 'referenceWriteLeases',(select count(*)from private.reference_write_intents where write_until>statement_timestamp()),
 'generationLeases',(select count(*)from private.generation_work where lease_until>statement_timestamp()),
 'generationCleanupLeases',(select count(*)from private.generation_work where cleanup_until>statement_timestamp()),
 'cleanupJobLeases',(select count(*)from private.cleanup_jobs where status='processing'and coalesce(lease_until,updated_at+interval '5 minutes')>statement_timestamp()),
 'apparelCleanupLeases',(select count(*)from private.apparel_storage_intents where cleanup_until>statement_timestamp()),
 'creativeBatchLeases',(select count(*)from public.creative_batches where lease_until>statement_timestamp()),
 'apparelRunLeases',(select count(*)from public.apparel_runs where status='processing'and lease_until>statement_timestamp()),
 'expiringGenerationsWithin22Minutes',(select count(*)from public.generations where asset_status='active'and asset_expires_at<=statement_timestamp()+interval '22 minutes'),
 'expiringReferencesWithin22Minutes',(select count(*)from public.reference_uploads where status='active'and upload_expires_at<=statement_timestamp()+interval '22 minutes'),
 'expiringApparelWithin22Minutes',(select count(*)from public.apparel_assets a join public.apparel_runs r on r.id=a.run_id where a.expires_at<=statement_timestamp()+interval '22 minutes'or r.status='processing'and r.lease_until+interval '10 minutes'<=statement_timestamp()+interval '22 minutes'),
 'dueOrphanResultIntents',(select count(*)from private.generation_work x where x.storage_path is not null and x.cleanup_next_at<=statement_timestamp()+interval '22 minutes'and not exists(select 1 from public.generations g join public.generation_batches b on b.id=g.batch_id join public.sessions s on s.id=b.session_id join public.account_profiles a on a.user_id=b.user_id where g.id=x.generation_id and s.status='active'and a.status='active'and(g.status in('pending','processing')or g.status='succeeded'and g.asset_status='active'))and(x.phase<>'cancelled'or exists(select 1 from storage.objects z where z.bucket_id='generated'and z.name=x.storage_path))),
 -- Deliberately conservative: a due apparel intent blocks without assuming it
 -- is live or querying Storage object payloads. False positives require review.
 'dueApparelIntents',(select count(*)from private.apparel_storage_intents where cleanup_next_at<=statement_timestamp()+interval '22 minutes')
 )as value)
select jsonb_build_object('schemaVersion',1,'checkedAt',statement_timestamp(),'scope','paired-m6-protected-rows-v1','protectedRows',(select jsonb_object_agg(relation,jsonb_build_object('rows',rows,'sha256',rows_sha256))from protected),'activity',(select value from counts),'cron',(select jsonb_agg(jsonb_build_object('jobname',jobname,'schedule',schedule,'active',active)order by jobname)from cron.job),'activityBarrierVersion',2,'activeJobsDefinition','; conservative barrier, overlaps allowed','activeLeasesDefinition','accountCleanupLeases+referenceCleanupLeases+referenceWriteLeases+generationLeases+generationCleanupLeases+cleanupJobLeases+apparelCleanupLeases+creativeBatchLeases+apparelRunLeases','proofReady',false)as sealed_financial_observation;
